# Try drawing X cross diagonals inside the frame
def make_x_diagonal():
    grid = [[0]*30 for _ in range(30)]

    # Frame borders
    top_row, bot_row = 1, 25
    left_col, right_col = 1, 28

    # Fill everything first
    for r in range(top_row, bot_row + 1):
        for c in range(left_col, right_col + 1):
            grid[r][c] = 5

    # Draw X diagonals on top of it
    for r in range(top_row, bot_row + 1):
        for c in range(left_col, right_col + 1):
            # Draw diagonals: (r-lower)+ (c-left)= (r-lower)+ (c-left) or (lower-r)=...
            # Simpler: check if (r - top_row) == (c - left_col) or (r - top_row) == (right_col - c)
            if (r - top_row) == (c - left_col) or (r - top_row) == (right_col - c):
                grid[r][c] = 1  # Different color

    return grid

